solution.text:
terraform {
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "2.5.3"
    }
  }
}

variable "sizes" {
  type = map(string)
  default = {
    lite = "m8i.xlarge"
    full = "m8i.2xlarge"
    wide = "m8i.4xlarge"
  }
}

resource "local_file" "template" {
  for_each = var.sizes
  filename = "${path.module}/out/sandbox-${each.key}.txt"
  content  = "instance_type = ${each.value}\n"
}

resource "terraform_data" "warm_pool" {
  input = { lite = 2, full = 2, wide = 0 }
}
